'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  // Extract data from formData (e.g., title, content)
  const title = formData.get('title');
  const content = formData.get('content');

  // Perform your database operation here to create the post
  // await db.post.create({ data: { title, content } });

  // On-demand revalidation using revalidateTag. 
  // This immediately purges the cache associated with the 'posts' tag.
  // The next request will be a cache MISS, blocking to fetch fresh data,
  // guaranteeing that no stale content is served to the user.
  revalidateTag('posts');
}

